"""Decode the gzip+base64 measurement blobs fetched from the Colab run."""
from __future__ import annotations

import base64
import csv
import gzip
import json
import pathlib

OUT = pathlib.Path(__file__).resolve().parent
EAGER = "@@EAGER@23519@"
GRAPH = "@@GRAPH@3725@"
COUNTER = "@@COUNTER@5664@"
BLOBS = {"results.csv": EAGER, "graph_results.csv": GRAPH, "counter_vs_adam.csv": COUNTER}


def decode(blob: str) -> bytes:
    # format: @@TAG@<raw_len>@<base64(gzip(csv))>
    parts = blob.split("@")
    assert parts[2] in ("EAGER", "GRAPH", "COUNTER"), parts[:3]
    return gzip.decompress(base64.b64decode(parts[4]))


def main() -> None:
    for name, blob in BLOBS.items():
        raw = decode(blob)
        (OUT / name).write_bytes(raw)
        with (OUT / name).open(newline="") as fh:
            rows = list(csv.DictReader(fh))
        print(f"{name}: {len(raw)} bytes, {len(rows)} rows")
    # JSON mirrors of the CSVs
    for csv_name, json_name in (("results.csv", "results.json"),
                                ("graph_results.csv", "graph_results.json"),
                                ("counter_vs_adam.csv", "counter_vs_adam.json")):
        with (OUT / csv_name).open(newline="") as fh:
            rows = list(csv.DictReader(fh))
        meta = {"device": "NVIDIA A100-SXM4-40GB", "torch": "2.11.0+cu130",
                "cuda": "13.0", "triton": "3.6.0",
                "commit_measured": "ab39b3f3b13fc663f58730e25eaf214f6ec17570"}
        (OUT / json_name).write_text(json.dumps({"meta": meta, "rows": rows}, indent=1))
        print(f"{json_name}: {len(rows)} rows")


if __name__ == "__main__":
    main()
